<script setup>
import { formatMXN } from '~~/shared/features/pricing/prices.js'
const page = ref(1)
const { data, status, error, refresh } = await useFetch('/api/orders', { query: { page } })
const labels = { PENDING_PAYMENT: 'Pendiente de pago', CONFIRMED: 'Confirmado', PREPARING: 'En preparación', SHIPPED: 'Enviado', DELIVERED: 'Entregado', CANCELED: 'Cancelado', PENDING: 'Pendiente', PAID: 'Pagado', PARTIALLY_REFUNDED: 'Reembolso parcial', REFUNDED: 'Reembolsado', FAILED: 'Fallido', NOT_REQUIRED: 'Sin cobro requerido', RECONCILING: 'En conciliación' }
</script>
<template><section class="mx-auto max-w-store px-4 py-12 md:px-8"><UiBreadcrumbs :items="[{ label: 'Mi cuenta', to: '/cuenta' }, { label: 'Mis pedidos' }]" /><h1 class="text-display-l font-bold">Mis pedidos</h1><UiLoading variant="list" v-if="status === 'pending'" label="Consultando pedidos" /><div v-else-if="error" role="alert" class="mt-6"><p>{{ error.statusCode === 401 ? 'Inicia sesión para consultar tus pedidos.' : 'Pedidos no disponibles.' }}</p><NuxtLink to="/cuenta" class="inline-flex min-h-11 items-center text-accent-text underline">Ir a mi cuenta</NuxtLink><UiButton class="ml-4" @click="refresh">Reintentar</UiButton></div><template v-else-if="data"><p v-if="!data.total" class="mt-6">Aún no hay pedidos vinculados a tu cuenta.</p><ul class="mt-6 grid gap-6"><li v-for="order in data.orders" :key="order.id" class="rounded-sm border border-line bg-surface p-4"><h2 class="font-semibold">Pedido {{ order.number }}</h2><p>{{ labels[order.status] }} · Pago: {{ labels[order.moneyStatus] }}</p><p class="font-mono">{{ formatMXN(order.totalMoneyCents) }} {{ order.currency }}</p><ul class="mt-3"><li v-for="(line, i) in order.lines" :key="i">{{ line.quantity }} × {{ line.name }} · {{ line.sku }} · {{ formatMXN(line.lineAfterCouponCents) }}</li></ul><details class="mt-3"><summary class="min-h-11 cursor-pointer">Historial del pedido</summary><ol><li v-for="(step,i) in order.history" :key="i">{{ step.date.slice(0,10) }} · {{ labels[step.status] }}</li></ol></details></li></ul><nav v-if="data.pages > 1" class="mt-6 flex items-center gap-4" aria-label="Páginas de pedidos"><UiButton :disabled="page <= 1" @click="page--">Anterior</UiButton><span>{{ page }} / {{ data.pages }}</span><UiButton :disabled="page >= data.pages" @click="page++">Siguiente</UiButton></nav></template></section></template>
